{"code":"import csv
import sys


def summarize(path: str) -> dict[str, int]:
    counts = {"ok": 0, "malformed": 0, "high": 0}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            # Bug 1 fix: Check if temperature exists before accessing
            if "temperature_c" not in row or row["temperature_c"] == "":
                counts["malformed"] += 1
                continue

            temperature = float(row["temperature_c"])

            # Bug 2 fix: Vendor's inclusive 350.0 upper limit means 350.0 is OK
            if temperature > 350.0:
                counts["high"] += 1
            else:
                counts["ok"] += 1
    return counts


if __name__ == "__main__":
    print(summarize(sys.argv[1]))","input_files":["broken-vendor-log-parser.py","vendor-maintenance-log.csv"],"filename":"fixed-vendor-log-parser.py"}

